package com.machinefault.api.repo;
import com.machinefault.api.domain.FaultNotification; import java.time.Instant; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param;
// Notification lookups include recipient ID so users cannot retrieve each other's messages.
public interface NotificationRepository extends JpaRepository<FaultNotification,Long>{List<FaultNotification> findTop100ByRecipientIdOrderByCreatedAtDesc(Long userId);List<FaultNotification> findTop100ByRecipientIdAndReadAtIsNullOrderByCreatedAtDesc(Long userId);Optional<FaultNotification> findByIdAndRecipientId(Long id,Long userId);@Modifying @Query("update FaultNotification n set n.readAt=:readAt where n.recipient.id=:userId and n.readAt is null") int markAllReadByRecipientId(@Param("userId") Long userId,@Param("readAt") Instant readAt);}
